// VULNERABLE Node.js / Express
app.post('/login', (req, res) => {
  // req.body is { username: ..., password: ... } — attacker controls values
  User.findOne({ username: req.body.username, password: req.body.password })
});

// Attack: send JSON body
// { "username": "admin", "password": { "$ne": null } }
// MongoDB evaluates: find user where username='admin' AND password != null
// Returns the admin user without knowing the password

// VULNERABLE
String filter = "(&(uid=" + username + ")(password=" + password + "))";
// Normal: (&(uid=alice)(password=secret))

// Attack: username = "admin)(&)"
// Resulting filter: (&(uid=admin)(&))(password=attacker_input))
// The (&) is always true; the password check is now outside the AND — bypassed
// Attacker logs in as admin with any password

// Java JDBC — prepared statement
String sql = "SELECT * FROM users WHERE username = ? AND password = ?";
PreparedStatement ps = conn.prepareStatement(sql);
ps.setString(1, username);  // Parameter 1: data, not SQL
ps.setString(2, password);  // Parameter 2: data, not SQL
ResultSet rs = ps.executeQuery();
// Even if username = "admin'--", the apostrophe is literal, not a SQL delimiter

-- Database: define the procedure once
CREATE PROCEDURE GetUser(@UserId INT)
AS BEGIN
    SELECT username, email FROM users WHERE id = @UserId;
END;

-- Application: call with a parameter (Java example)
CallableStatement cs = conn.prepareCall("{call GetUser(?)}");
cs.setInt(1, userId);  -- Bound as an integer parameter, not SQL
ResultSet rs = cs.executeQuery();

-- VULNERABLE stored procedure — dynamic SQL with concatenation
CREATE PROCEDURE SearchUsers(@SearchTerm NVARCHAR(100))
AS BEGIN
    DECLARE @sql NVARCHAR(500);
    SET @sql = 'SELECT * FROM users WHERE username LIKE ''%' + @SearchTerm + '%''';
    EXEC(@sql);  -- STILL INJECTABLE
END;
